"""Shared editorial components for public-facing local pages."""
import os
import news,seo,search_visibility
from urllib.parse import urlencode

def city(m=''):
 return next((x['name'] for x in news.read('municipalities') if x['slug']==m),'provincie Utrecht')
def breadcrumb(parts):
 return '<nav class="breadcrumbs" aria-label="Kruimelpad">'+''.join(('<span aria-current="page">'+news.e(label)+'</span>' if i==len(parts)-1 else '<a href="'+news.e(path)+'">'+news.e(label)+'</a><span aria-hidden="true">/</span>') for i,(label,path) in enumerate(parts))+'</nav>'
def heading(m,category,total,period,q=''):
 label=('Zoekresultaten voor “'+q+'”') if q else (news.CATEGORIES.get(category,'')+' in '+city(m) if category else 'Het nieuws uit '+city(m))
 return '<header class="edition-heading"><div><p class="eyebrow">'+('UIT HET ARCHIEF' if period=='archive' else 'DICHTBIJ EN VAN BELANG' if period=='all' else 'DICHTBIJ EN VAN BELANG')+'</p><h2>'+news.e(label)+'</h2></div><div><a href="/nieuws/dossiers">Volg een dossier ›</a></div></header>'
def city_links(m=''):
 place=city(m);root=news.BASE+('/'+m if m else '')
 return '<section class="local-discover"><div><p class="eyebrow">MEER UIT '+news.e(place.upper())+'</p><h2>Jouw omgeving, op één plek.</h2></div><div class="discover-links"><a href="'+root+'"><strong>Het lokale nieuws</strong><span>Besluiten, veiligheid en bereikbaarheid ›</span></a><a href="'+seo.agenda_path(m)+'"><strong>De gemeenteagenda</strong><span>Activiteiten uit PITO, dichtbij jou ›</span></a><a href="'+seo.agenda_path(m,'vandaag')+'"><strong>Vandaag te doen</strong><span>Bekijk wat er in de agenda staat ›</span></a><a href="'+root+'?weergave=community"><strong>Verhalen uit de buurt</strong><span>Van bewoners en lokale initiatieven ›</span></a></div></section>'
def share_tools(a):
 return '<div class="article-tools"><span>'+str(max(1,round(len(a['body'].split())/200)))+' min leestijd</span><button type="button" data-copy-link>Kopieer link</button><button type="button" data-share hidden>Deel artikel</button><span class="share-status" role="status" aria-live="polite"></span></div>'
def trustbar():
 return '<div class="editorial-trust"><span>Nieuws met een bron</span><a href="/nieuws/over-de-redactie">Zo werkt onze redactie</a><a href="/nieuws/bronnen">Onze bronnen</a><a href="/nieuws/selectie">Waarom dit nieuws?</a></div>'
def about():
 edition='<p>PITO Nieuws volgt de 26 gemeenten in de provincie Utrecht. Het archief en de bronselectie zijn niet volledig. Een artikel vermeldt zijn bronnen en de beschikbare publicatie- en updategegevens. De agenda gebruikt de gedeelde activiteiten uit PITO.</p>'
 if os.environ.get('PITO_PUBLIC_PREVIEW')=='1':
  edition='<p>Je bekijkt de publieke proefversie van PITO Nieuws. Historische nieuwsconcepten zijn hier zichtbaar om de website te beoordelen. Ze zijn daarmee niet als nieuw nieuws gepubliceerd. De actuele agenda is alleen zichtbaar wanneer de gedeelde PITO-bron beschikbaar is.</p>'
 elif not search_visibility.production():
  edition='<p>Je bekijkt een lokale proefomgeving. Historische nieuwsconcepten en opgeslagen activiteiten zijn hier zichtbaar om de website te beoordelen. Ze zijn daarmee niet als nieuw nieuws gepubliceerd.</p>'
 body=breadcrumb([('PITO','/'),('Nieuws',news.BASE),('Over de redactie','/nieuws/over-de-redactie')])+'''<section class="section editorial-about"><p class="eyebrow">PITO NIEUWS</p><h1>Dichtbij. Duidelijk.<br>Controleerbaar.</h1><p class="standfirst">PITO verzamelt wat inwoners helpt hun omgeving te begrijpen: van een besluit in de gemeenteraad tot een afsluiting op jouw route.</p><div class="editorial-principles"><section><span>01</span><h2>Een bron bij elk verhaal</h2><p>Bij nieuwsartikelen verwijzen we naar de publicaties waarop ze zijn gebaseerd. Een eigen tekst legt uit wat er verandert, voor wie en wanneer. Bronmateriaal en de onderbouwing blijven apart van het openbare artikel bewaard.</p></section><section><span>02</span><h2>Een besluit is geen voorstel</h2><p>Raadsagenda’s, plannen en vastgestelde besluiten hebben een verschillende betekenis. De datum van een bron, de datum van een gebeurtenis en onze eigen publicatie- of updatedatum blijven gescheiden.</p></section><section><span>03</span><h2>Automatisch en redactioneel</h2><p>Een deel van de praktische berichten kan automatisch worden samengesteld uit vooraf toegestane primaire bronnen. Automatische controles toetsen onder meer de herkomst, datering, gemeente en onderbouwing. Ze bewijzen niet dat een bron of tekst inhoudelijk juist is.</p><p>Bij een automatisch samengesteld artikel staat dat vermeld. Een menselijke beoordelaar wordt alleen genoemd als die het bericht werkelijk heeft beoordeeld. Gevoelige of onduidelijke berichten vallen buiten de automatische publicatie en wachten op redactionele beoordeling.</p></section><section><span>04</span><h2>Herkenbare afzenders</h2><p>Communitybijdragen vermelden de auteursnaam. PITO-promoties zijn herkenbaar als advertentie. Een nieuwsbron is niet automatisch een commerciële partner; commerciële afspraken zijn geen criterium voor de nieuwsrangschikking.</p></section></div><div class="sourcebox"><h2>Over deze lokale editie</h2>'''+edition+'''<p>Klopt iets niet? Vermeld de artikellink en welke informatie een correctie ondersteunt via <a href="https://pito.app/?page=contact">Contact met PITO</a>. Lees meer over <a href="/nieuws/verantwoording#correcties">correcties en reacties</a>.</p></div><a class="button" href="/nieuws/meedoen">Help mee als lokale redacteur</a></section>'''
 return news.layout('Over de redactie',body,'/nieuws/over-de-redactie','Hoe PITO Nieuws bronnen, automatische verwerking, redactionele beoordeling en correcties herkenbaar maakt.')
